async function main() {
  // Read trial_id from /logs/trial_id
  const trialId = fs.readFileSync("/logs/trial_id", "utf-8").trim();
  const channelName = `agent-results-${trialId}`;

  console.log(`Trial ID: ${trialId}`);
  console.log(`Slack channel: ${channelName}`);

  // Configure OpenAI with proxy support if available
  const proxyUrl = process.env.https_proxy || process.env.HTTPS_PROXY;

  let customFetch: typeof fetch | undefined;
  if (proxyUrl) {
    const proxyAgent = new ProxyAgent(proxyUrl);
    customFetch = (url, options) =>
      undiciFetch(url as string, {
        ...options,
        dispatcher: proxyAgent,
      } as Parameters<typeof undiciFetch>[1]) as unknown as Promise<Response>;
  }

  const openai = createOpenAI({
    apiKey: process.env.OPENAI_API_KEY,
    fetch: customFetch,
  });

  // Initialize Composio with VercelProvider
  const composio = new Composio({
    provider: new VercelProvider(),
  });

  // Get tools directly for user zealt-user01
  const tools = await composio.tools.get("zealt-user01", {
    tools: ["GITHUB_GET_A_USER", "SLACK_SENDS_A_MESSAGE_TO_A_SLACK_CHANNEL"],
  });

  console.log("Tools loaded:", Object.keys(tools));

  // Use generateText to run the agent
  const result = await generateText({
    model: openai("gpt-4o"),
    tools,
    maxSteps: 10,
    prompt: `You are a helpful agent. Please do the following steps in order:

1. Fetch the GitHub profile of the user "composiohq" using the GITHUB_GET_A_USER tool.
2. Extract the user's "bio" and "public_repos" count from the response.
3. Post a message to the Slack channel named "${channelName}" with this exact format:
   "User composiohq has {public_repos} repos. Bio: {bio}"
   (Replace {public_repos} with the actual number and {bio} with the actual bio text.)

Make sure to complete all three steps.`,
  });

  console.log("Agent completed.");
  console.log("Final text:", result.text);
}

main().catch((err) => {
  console.error("Error:", err);
  process.exit(1);
});

